mutation PatchServiceEnvironment($serviceId: String!, $envVars: [EnvironmentEnvVarPatchInput!], $secretFiles: [EnvironmentSecretFilePatchInput!], $saveMode: String!) {
  patchServiceEnvironment(
    serviceId: $serviceId
    envVars: $envVars
    secretFiles: $secretFiles
    saveMode: $saveMode
  ) {
    envVarKeys
    secretFileNames
    rolledOut
    __typename
  }
}

